        const char *current_file = archive_entry_pathname(entry);
        if (!is_path_safe(current_file)) {
            archive_read_free(a);
            archive_write_free(ext);
            return false;
        }
        archive_read_data_skip(a);
    }

    // Reset archive for second pass
    archive_read_free(a);
    a = archive_read_new();
    archive_read_support_filter_all(a);
    archive_read_support_format_all(a);

    if (archive_read_open_filename(a, tar_path, 10240) != ARCHIVE_OK) {
        archive_read_free(a);
        archive_write_free(ext);
        return false;
    }

    // Second pass: extract files
    while ((r = archive_read_next_header(a, &entry)) == ARCHIVE_OK) {
        const char *current_file = archive_entry_pathname(entry);
        char full_path[PATH_MAX];
        snprintf(full_path, PATH_MAX, "%s/%s", dest_path, current_file);

        archive_entry_set_pathname(entry, full_path);

        r = archive_write_header(ext, entry);
        if (r != ARCHIVE_OK) {
            archive_read_free(a);
            archive_write_free(ext);
            return false;
        }

        // Copy data
        const void *buff;
        size_t size;
        la_int64_t offset;

        while (archive_read_data_block(a, &buff, &size, &offset) == ARCHIVE_OK) {
            if (archive_write_data_block(ext, buff, size, offset) != ARCHIVE_OK) {
                archive_read_free(a);
                archive_write_free(ext);
                return false;
            }
        }
    }

    archive_read_free(a);
    archive_write_free(ext);

    return r == ARCHIVE_EOF ? true : false;
}

int is_path_safe(const char *path) {
    if (path[0] == '/') {  // Check for absolute path
        return false;
    }

    char *path_copy = strdup(path);
    char *token = strtok(path_copy, "/");

    while (token != NULL) {
        if (strcmp(token, "..") == 0) {
            free(path_copy);
            return false;
        }
        token = strtok(NULL, "/");
    }

    free(path_copy);
    return true;
}

